use verus::prelude::*;

verus! {

    /// Returns the number of turns needed to defeat an opponent
    /// with `health` HP and `strength` attack power.
    ///   ⌈health/strength⌉ = (health + strength − 1)/strength
    fn exec_turns_to_defeat(health: i8, strength: i8) -> i64
        requires(1 <= health && health <= 100
              && 1 <= strength && strength <= 100)
        ensures(result == ((health as i64 + strength as i64 - 1) / strength as i64))
    {
        let health64: i64 = health as i64;
        let strength64: i64 = strength as i64;
        (health64 + strength64 - 1) / strength64
    }

    /// Given Takahashi’s health `a`, his attack `b`, Aoki’s health `c`, and attack `d`,
    /// returns "Yes" if Takahashi defeats Aoki in no more turns than Aoki would defeat him,
    /// else returns "No".
    fn solve(a: i8, b: i8, c: i8, d: i8) -> &'static str
        requires(
            1 <= a && a <= 100 &&
            1 <= b && b <= 100 &&
            1 <= c && c <= 100 &&
            1 <= d && d <= 100
        )
        ensures(
            if exec_turns_to_defeat(c, b) <= exec_turns_to_defeat(a, d) {
                result == "Yes"
            } else {
                result == "No"
            }
        )
    {
        let takahashi_turns = exec_turns_to_defeat(c, b);
        let aoki_turns     = exec_turns_to_defeat(a, d);
        if takahashi_turns <= aoki_turns {
            "Yes"
        } else {
            "No"
        }
    }
}